# Fused RMSNorm + Linear kernel for q projection
rmsnorm_linear_q_cpp_source = """
#include <hip/hip_runtime.h>
#include <hip/hip_fp16.h>

#define TILE_M 32
#define TILE_N 64
#define TILE_K 16

__global__ void fused_rmsnorm_linear_q_kernel(
    const float* input,
    const float* norm_weight,
    const float* weight,
    float* output,
    int m,
    int n,
    int k,
    float eps
) {
    int row = blockIdx.x;
    int col = blockIdx.y * blockDim.x + threadIdx.x;

    if (row >= m || col >= n) return;

    // RMSNorm computation
    float sum_sq = 0.0f;
    for (int i = 0; i < k; i++) {
        float val = input[row * k + i];
        sum_sq += val * val;
    }
    float mean = sum_sq / (float)k;
    float rsqrt = rsqrtf(mean + eps);

    // Linear projection
    float result = 0.0f;
    for (int i = 0; i < k; i++) {
        float normalized_val = input[row * k + i] * rsqrt * norm_weight[i];
        result += normalized_val * weight[col * k + i];
    }

    output[row * n + col] = result;
}

torch::Tensor fused_rmsnorm_linear_q(
    torch::Tensor input,
    torch::Tensor norm_weight,
    torch::Tensor weight,
    float eps
) {
    int m = input.size(0) * input.size(1); // flattened batch+seq
    int n = weight.size(0);
    int k = input.size(2);

    auto output = torch::zeros_like(input.view(m, k));
    output = output.view({input.size(0), input.size(1), n});

    output = output.contiguous().view({m, n});

    const int block_size = 256;
    dim3 grid((m + block_size - 1) / block_size, (n + block_size - 1) / block_size);

    hipLaunchKernelGGL(
        fused_rmsnorm_linear_q_kernel,
        dim3(m, (n + 255) / 256),
        256,
        0, 0,
        input.data_ptr<float>(),
        norm_weight.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        m, n, k, eps
    );

    return output.view({input.size(0), input.size(1), n});
}
"""

