#include <hip/hip_runtime.h>

__global__ void rope_kernel(
    const float* q_in,
    const float* k_in,
    const float* cos,
    const float* sin,
    float* q_out,
    float* k_out,
    int batch_size,
    int num_heads,
    int seq_len,
    int head_dim,
    int rope_dim
) {
    int batch = blockIdx.x;
    int head = blockIdx.y;
    int seq = blockIdx.z * blockDim.x + threadIdx.x;

    if (seq >= seq_len) return;

    int out_idx = ((batch * num_heads + head) * seq_len + seq) * head_dim;
    int cos_idx = seq * rope_dim;

    // Apply to last rope_dim elements
    for (int i = 0; i < rope_dim / 2; i++) {
        int idx = out_idx + head_dim - rope_dim + i * 2;
        int offset = i * 2;

        float q_x1 = q_in[idx];
        float q_x2 = q_in[idx + 1];
        float c = cos[cos_idx + offset];
        float s = sin[cos_idx + offset];

        q_out[idx] = q_x1 * c - q_x2 * s;
        q_out[idx + 1] = q_x1 * s + q_x2 * c;

        float k_x1 = k_in[idx];
